<?php require_once dirname(__DIR__) . '/header.php'; ?><main class="page-layout"><section class="tool-content"><div class="desktop-ad ad-slot"><?php smartToozAd('top_desktop'); ?></div><div class="mobile-ad ad-slot"><?php smartToozAd('top_mobile'); ?></div><div class="tool-header"><span class="tool-badge">IMAGE & GIF TOOL</span><h1>GIF <span>Maker</span></h1><p>Create an animated GIF from multiple images. Arrange frames, control speed and download your finished GIF.</p></div><div class="maker-card"><div class="upload-area" id="uploadArea"><div class="upload-icon">🎞️</div><h2>Upload Images</h2><p>Click here or drag & drop multiple JPG, PNG or WebP images</p><p class="file-info" id="fileInfo">No images selected</p><input id="fileInput" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><div class="frames" id="frames"><div class="frames-header"><h2>GIF Frames</h2><button class="btn btn-secondary" type="button" id="addMore">+ Add Images</button></div><div class="frames-grid" id="framesGrid"></div></div><div class="settings" id="settings"><div class="setting-row"><div class="setting-top"><label>Frame Delay</label><span class="value" id="delayValue">500 ms</span></div><input id="delay" type="range" min="100" max="2000" step="50" value="500"></div><div class="setting-row"><div class="setting-top"><label>GIF Width</label><span class="value" id="widthValue">Auto</span></div><input id="width" type="range" min="160" max="1000" step="10" value="0"></div></div><div class="actions"><button class="btn btn-primary" id="createBtn" type="button" disabled>Create GIF</button><button class="btn btn-secondary" id="resetBtn" type="button">Reset</button></div><div class="error" id="error"></div><div class="result" id="result"><img class="result-preview" id="resultPreview" alt="Generated GIF preview"><div class="result-info"><div class="stat"><strong id="frameCount">0</strong><span>Frames</span></div><div class="stat"><strong id="gifSize">0 KB</strong><span>GIF Size</span></div><div class="stat"><strong id="gifTime">0 ms</strong><span>Duration</span></div></div><div class="actions"><button class="btn btn-primary" id="downloadBtn" type="button">Download GIF</button></div></div></div><div class="info-box"><h2>How to Make a GIF</h2><p>Upload two or more images, arrange them as frames, choose the frame delay and create your animated GIF. Processing happens in your browser.</p><ul><li>Use images with similar dimensions for the best result.</li><li>A smaller frame delay makes the animation faster.</li><li>Your images are processed locally in your browser.</li></ul></div><div class="desktop-ad ad-slot"><?php smartToozAd('bottom_desktop'); ?></div><div class="mobile-ad ad-slot"><?php smartToozAd('bottom_mobile'); ?></div></section><aside class="tools-sidebar"><?php require_once __DIR__.'/tool-sidebar.php'; ?></aside></main><footer><strong>Smart-Tooz</strong><p>Free online tools made simple.</p></footer><script src="https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.min.js"></script><script>
const input=document.getElementById('fileInput'),area=document.getElementById('uploadArea'),grid=document.getElementById('framesGrid'),framesBox=document.getElementById('frames'),settings=document.getElementById('settings'),createBtn=document.getElementById('createBtn'),resetBtn=document.getElementById('resetBtn'),addMore=document.getElementById('addMore'),fileInfo=document.getElementById('fileInfo'),errorBox=document.getElementById('error'),result=document.getElementById('result'),preview=document.getElementById('resultPreview'),downloadBtn=document.getElementById('downloadBtn');let images=[],gifBlob=null,workerUrl=null;
function showError(m){errorBox.textContent=m;errorBox.style.display='block'}function clearError(){errorBox.textContent='';errorBox.style.display='none'}function render(){grid.innerHTML='';images.forEach((x,i)=>{const d=document.createElement('div');d.className='frame';d.innerHTML='<button class="remove-frame" type="button" data-i="'+i+'">×</button><img src="'+x.src+'" alt="Frame '+(i+1)+'"><span>Frame '+(i+1)+'</span>';grid.appendChild(d)});framesBox.style.display=images.length?'block':'none';settings.style.display=images.length>1?'block':'none';createBtn.disabled=images.length<2;fileInfo.textContent=images.length?images.length+' image'+(images.length>1?'s':'')+' selected':'No images selected'}function addFiles(files){clearError();[...files].forEach(file=>{if(!['image/jpeg','image/png','image/webp'].includes(file.type)){showError('Only JPG, PNG and WebP images are supported.');return}const r=new FileReader();r.onload=e=>{const im=new Image();im.onload=()=>{images.push({src:e.target.result,img:im});render()};im.src=e.target.result};r.readAsDataURL(file)});input.value=''}area.onclick=()=>input.click();input.onchange=e=>addFiles(e.target.files);addMore.onclick=()=>input.click();['dragenter','dragover'].forEach(t=>area.addEventListener(t,e=>{e.preventDefault();area.classList.add('dragover')}));['dragleave','drop'].forEach(t=>area.addEventListener(t,e=>{e.preventDefault();area.classList.remove('dragover')}));area.addEventListener('drop',e=>addFiles(e.dataTransfer.files));grid.onclick=e=>{if(e.target.classList.contains('remove-frame')){images.splice(Number(e.target.dataset.i),1);render();result.style.display='none'}};document.getElementById('delay').oninput=e=>document.getElementById('delayValue').textContent=e.target.value+' ms';document.getElementById('width').oninput=e=>document.getElementById('widthValue').textContent=e.target.value==0?'Auto':e.target.value+' px';
async function getWorkerUrl(){if(workerUrl)return workerUrl;const r=await fetch('https://cdn.jsdelivr.net/npm/gif.js@0.2.0/dist/gif.worker.js',{mode:'cors',cache:'force-cache'});if(!r.ok)throw new Error('GIF worker download failed');workerUrl=URL.createObjectURL(new Blob([await r.text()],{type:'application/javascript'}));return workerUrl}
createBtn.onclick=async()=>{clearError();if(images.length<2){showError('Please select at least 2 images.');return}createBtn.disabled=true;createBtn.textContent='Preparing...';try{const delay=Number(document.getElementById('delay').value),requested=Number(document.getElementById('width').value),first=images[0].img,nativeWidth=first.naturalWidth||first.width,nativeHeight=first.naturalHeight||first.height,width=requested||nativeWidth,height=Math.max(1,Math.round(width*nativeHeight/nativeWidth)),workerScript=await getWorkerUrl(),gif=new GIF({workers:2,quality:10,width,height,workerScript});images.forEach(x=>gif.addFrame(x.img,{delay,copy:true}));gif.on('progress',p=>createBtn.textContent='Creating GIF '+Math.round(p*100)+'%');gif.on('finished',blob=>{gifBlob=blob;preview.src=URL.createObjectURL(blob);document.getElementById('frameCount').textContent=images.length;document.getElementById('gifSize').textContent=(blob.size/1024).toFixed(1)+' KB';document.getElementById('gifTime').textContent=(images.length*delay)+' ms';result.style.display='block';createBtn.disabled=false;createBtn.textContent='Create GIF'});gif.render()}catch(e){console.error(e);showError('GIF creation failed. Please try again.');createBtn.disabled=false;createBtn.textContent='Create GIF'}};downloadBtn.onclick=()=>{if(!gifBlob)return;const a=document.createElement('a');a.href=URL.createObjectURL(gifBlob);a.download='smarttoolz.gif';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};resetBtn.onclick=()=>{images=[];gifBlob=null;result.style.display='none';clearError();render()};render();
</script>

